CREATE TABLE pages (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, slug text NOT NULL, public_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), draft_tree jsonb NOT NULL, published_version_id uuid, published_at timestamptz, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX pages_org_slug_uidx ON pages (org_id, slug); ALTER TABLE pages ENABLE ROW LEVEL SECURITY; CREATE POLICY pages_isolation_by_org ON pages FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE page_versions (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE, version integer NOT NULL, tree jsonb NOT NULL, html text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX page_versions_page_version_uidx ON page_versions (page_id, version); CREATE INDEX page_versions_org_page_idx ON page_versions (org_id, page_id); ALTER TABLE page_versions ENABLE ROW LEVEL SECURITY; CREATE POLICY page_versions_isolation_by_org ON page_versions FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid); ALTER TABLE pages ADD CONSTRAINT pages_published_version_fk FOREIGN KEY (published_version_id) REFERENCES page_versions(id);
CREATE TABLE page_public_keys (public_key text PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON pages, page_versions TO app_user; ALTER PUBLICATION electric_publication_default ADD TABLE pages, page_versions;
UPDATE permission_groups SET capabilities = capabilities || '["pages:read", "pages:write"]'::jsonb, updated_at = now() WHERE name IN ('Proprietário','Administrador','Gerente','Agente') AND NOT capabilities @> '["pages:read", "pages:write"]'::jsonb; UPDATE permission_groups SET capabilities = capabilities || '["pages:read"]'::jsonb, updated_at = now() WHERE name = 'Visualizador' AND NOT capabilities @> '["pages:read"]'::jsonb;
